import { precacheAndRoute, matchPrecache } from 'workbox-precaching';
import { registerRoute, setCatchHandler } from 'workbox-routing';
import { NetworkFirst, StaleWhileRevalidate, CacheFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// Precache application shell assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Immediately take control of the page
self.skipWaiting();

// 1. Dicoding Story API: NetworkFirst with 24-hour expiration (maxEntries: 50)
registerRoute(
  ({ url, request }) =>
    request.method === 'GET' &&
    url.origin === 'https://story-api.dicoding.dev' &&
    url.pathname.startsWith('/v1/stories'),
  new NetworkFirst({
    cacheName: 'dicoding-story-api',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60, // 24 hours
      }),
    ],
  }),
);

// 2. Remote Story Images: StaleWhileRevalidate with 7-day expiration (maxEntries: 60)
registerRoute(
  ({ url, request }) =>
    request.method === 'GET' &&
    url.origin === 'https://story-api.dicoding.dev' &&
    (url.pathname.includes('/images/') || request.destination === 'image'),
  new StaleWhileRevalidate({
    cacheName: 'dicoding-story-images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 7 * 24 * 60 * 60, // 7 days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  }),
);

// 3. Third-party static assets: Leaflet CDN assets (unpkg)
registerRoute(
  ({ url }) => url.origin === 'https://unpkg.com' && url.pathname.includes('leaflet'),
  new CacheFirst({
    cacheName: 'leaflet-cdn-assets',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  }),
);

// 4. Third-party static assets: Map tile providers (OSM, OpenTopoMap, Esri)
registerRoute(
  ({ url }) =>
    url.hostname.endsWith('tile.openstreetmap.org') ||
    url.hostname.endsWith('tile.opentopomap.org') ||
    url.hostname.includes('arcgisonline.com'),
  new CacheFirst({
    cacheName: 'leaflet-map-tiles',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 14 * 24 * 60 * 60, // 14 days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  }),
);

// 5. Third-party static assets: Google Fonts (stylesheets & webfonts)
registerRoute(
  ({ url }) =>
    url.origin === 'https://fonts.googleapis.com' ||
    url.origin === 'https://fonts.gstatic.com',
  new CacheFirst({
    cacheName: 'google-fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 365 * 24 * 60 * 60, // 1 year
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  }),
);

// Graceful offline fallback handler for failed network requests without cache
setCatchHandler(async ({ request, url }) => {
  const targetUrl = url || (request ? new URL(request.url) : null);

  // Return precached index.html for navigation requests
  if (request && (request.destination === 'document' || request.mode === 'navigate')) {
    return (await matchPrecache('index.html')) || Response.error();
  }

  // Graceful offline JSON response for Story API endpoints
  if (
    targetUrl &&
    (targetUrl.origin === 'https://story-api.dicoding.dev' ||
      targetUrl.pathname?.startsWith('/v1/stories'))
  ) {
    return new Response(
      JSON.stringify({
        error: true,
        message: 'Koneksi internet terputus. Data cerita ini belum tersedia di cache offline.',
      }),
      {
        status: 503,
        statusText: 'Service Unavailable (Offline)',
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );
  }

  // Graceful offline SVG placeholder for images
  if (request && request.destination === 'image') {
    return new Response(
      `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300" viewBox="0 0 400 300">
        <rect width="100%" height="100%" fill="#e2e8f0"/>
        <text x="50%" y="50%" fill="#64748b" font-family="sans-serif" font-size="14" text-anchor="middle" dominant-baseline="middle">Gambar tidak tersedia saat offline</text>
      </svg>`,
      {
        status: 200,
        headers: {
          'Content-Type': 'image/svg+xml',
          'Cache-Control': 'no-store',
        },
      },
    );
  }

  return Response.error();
});
